def minimum_equal_path_increments(n,cost):
    cost=cost.copy();answer=0
    for node in range(n//2,0,-1):
        left=cost[2*node-1];right=cost[2*node]
        answer+=abs(left-right);cost[node-1]+=max(left,right)
    return answer

